r("GameAudio.setVolume(.25);GameAudio.sync()");assert.equal(disk['353-audio-volume'],'0.25');assert(Math.abs(sounds.at(-1).volume-.42*.25)<1e-8);r("GameAudio.se('fine')");assert(Math.abs(sounds.at(-1).volume-.65*.25)<1e-8);r("GameAudio.setVolume(0)");assert(sounds.filter(a=>!a.paused).every(a=>a.volume===0));r("GameAudio.setVolume(2)");assert.equal(disk['353-audio-volume'],'1');r("GameAudio.setVolume(NaN)");assert.equal(disk['353-audio-volume'],'1');r("state.phase='epilogue';state.epStep=3;GameAudio.sync();GameAudio.setVolume(.5)");assert(sounds.every(a=>a.paused));r("state.phase='desktop';state.progress.ah=0;GameAudio.reset();GameAudio.sync()");assert(Math.abs(sounds.at(-1).volume-.42*.5)<1e-8);console.log('PASS v1.0.3: master volume scales music/effects, clamps values, persists, survives restart, and cannot interrupt epilogue silence.');
